518	  repeated Memo memos = 1;
519	
520	  // A token for the next page of results.
521	  string next_page_token = 2;
522	}
523	
524	message ListMemoReactionsRequest {
525	  // Required. The resource name of the memo.
526	  // Format: memos/{memo}
527	  string name = 1 [
528	    (google.api.field_behavior) = REQUIRED,
529	    (google.api.resource_reference) = {type: "memos.api.v1/Memo"}
530	  ];
531	
532	  // Optional. The maximum number of reactions to return.
533	  int32 page_size = 2 [(google.api.field_behavior) = OPTIONAL];
534	
535	  // Optional. A page token for pagination.
536	  string page_token = 3 [(google.api.field_behavior) = OPTIONAL];
537	}
538	
539	message ListMemoReactionsResponse {
540	  // The list of reactions.
541	  repeated Reaction reactions = 1;
542	
543	  // A token for the next page of results.
544	  string next_page_token = 2;
545	}
546	
547	message UpsertMemoReactionRequest {
548	  // Required. The resource name of the memo.
549	  // Format: memos/{memo}
550	  string name = 1 [
551	    (google.api.field_behavior) = REQUIRED,
552	    (google.api.resource_reference) = {type: "memos.api.v1/Memo"}
553	  ];
554	
555	  // Required. The reaction to upsert.
556	  Reaction reaction = 2 [(google.api.field_behavior) = REQUIRED];
557	}
558	
559	message DeleteMemoReactionRequest {
560	  // Required. The resource name of the reaction to delete.
561	  // Format: memos/{memo}/reactions/{reaction}
562	  string name = 1 [
563	    (google.api.field_behavior) = REQUIRED,
564	    (google.api.resource_reference) = {type: "memos.api.v1/Reaction"}
565	  ];
566	}
567	
568	// MemoShare is an access grant that permits read-only access to a memo via an opaque bearer token.
569	message MemoShare {
570	  option (google.api.resource) = {
571	    type: "memos.api.v1/MemoShare"
572	    pattern: "memos/{memo}/shares/{share}"
573	    singular: "share"
574	    plural: "shares"
575	  };
576	
577	  // The resource name of the share. Format: memos/{memo}/shares/{share}
578	  // The {share} segment is the opaque token used in the share URL.
579	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
580	
581	  // Output only. When this share link was created.
582	  google.protobuf.Timestamp create_time = 2 [(google.api.field_behavior) = OUTPUT_ONLY];
583	
584	  // Optional. When set, the share link stops working after this time.
585	  // If unset, the link never expires.
586	  optional google.protobuf.Timestamp expire_time = 3 [(google.api.field_behavior) = OPTIONAL];
587	}
588	
589	message CreateMemoShareRequest {
590	  // Required. The resource name of the memo to share.
591	  // Format: memos/{memo}
592	  string parent = 1 [
593	    (google.api.field_behavior) = REQUIRED,
594	    (google.api.resource_reference) = {type: "memos.api.v1/Memo"}
595	  ];
596	
597	  // Required. The share to create.
598	  MemoShare memo_share = 2 [(google.api.field_behavior) = REQUIRED];
599	}
600	
601	message ListMemoSharesRequest {
602	  // Required. The resource name of the memo.
603	  // Format: memos/{memo}
604	  string parent = 1 [
605	    (google.api.field_behavior) = REQUIRED,
606	    (google.api.resource_reference) = {type: "memos.api.v1/Memo"}
607	  ];
608	}
609	
610	message ListMemoSharesResponse {
611	  // The list of share links.
612	  repeated MemoShare memo_shares = 1;
613	}
614	
615	message DeleteMemoShareRequest {
616	  // Required. The resource name of the share to delete.
617	  // Format: memos/{memo}/shares/{share}
618	  string name = 1 [
619	    (google.api.field_behavior) = REQUIRED,
620	    (google.api.resource_reference) = {type: "memos.api.v1/MemoShare"}
621	  ];
622	}
623	
624	message GetMemoByShareRequest {
625	  // Required. The share token extracted from the share URL (/s/{share_id}).
626	  string share_id = 1 [(google.api.field_behavior) = REQUIRED];
627	}
628	
629	message GetLinkMetadataRequest {
630	  // Required. The link URL.
631	  string url = 1 [(google.api.field_behavior) = REQUIRED];
632	}
633	
634	message BatchGetLinkMetadataRequest {
635	  // Required. The link URLs.
636	  repeated string urls = 1 [(google.api.field_behavior) = REQUIRED];
637	}
638	
639	message BatchGetLinkMetadataResponse {
640	  // The link metadata list, in the same order as the input URLs.
641	  repeated LinkMetadata link_metadata = 1;
642	}
643	
644	message LinkMetadata {
645	  // The original link URL.
646	  string url = 1;
647	
648	  // The link title.
